"""Install credential-free rollover validation; never starts a production run."""
import os,hashlib,base64,fcntl,subprocess,time,tempfile
from pathlib import Path
MANIFEST={'automation/validate_season.ps1': {'old': '9e3426bdf89a5eed8e4e3bcc994d576960d2ec61f70b5b2349f0849588340f79', 'new': '0b64ea2ac8128f7a653a30a24eb809ff4b48acb449a1cfda50ea4af15e3c27b2', 'body': ''}, 'automation/start_new_season.ps1': {'old': '46b390be82fb594c57a8009ef555d44388ddd39be6857c28f29d92cf4ddada33', 'new': '4586a7322b2de385c58fc305bec4eddd4da7fab8bcb57c794eafde147ac61856', 'body': ''}, 'automation/server/editor-prompt.md': {'old': 'c67f656ecd6c5638ef498776821f24a6d3110d162242e1056a893016c90db08f', 'new': 'b97d15ec6f1896ada535eb85fee86a9ec4bd4366dfa67ae9f7bec5fddefa5d50', 'body': ''}, 'automation/test_rollover_validation.py': {'old': None, 'new': '14bcd5638ce10723756ba95152b9333ac8f7a40428be1362abc11ac7ef7183d0', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.handoff-install-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    assert __import__('shutil').which('pwsh'), 'PowerShell required; nothing changed'
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');prepared={}
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new']
        if n.endswith('.py'):compile(raw,str(p),'exec')
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        backup=store/'repairs'/('rollover-validation-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(before);saved.chmod(0o600)
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
            subprocess.run(['/usr/bin/python3','automation/test_rollover_validation.py'],cwd=root,check=True,timeout=180)
            subprocess.run(['/usr/bin/python3','-m','unittest','test_editor_handoff','test_recovery','test_install_recovery'],cwd=root/'automation/server',check=True,timeout=90)
            subprocess.run(['/usr/bin/python3','automation/test_refresh_guard.py'],cwd=root,check=True,timeout=90)
            subprocess.run(['/usr/bin/python3','automation/test_portable_report.py'],cwd=root,check=True,timeout=240)
        except Exception:
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            raise
        print('ROLLOVER_VALIDATION_INSTALLED content validation separated; full publication checks retained; no production refresh started',flush=True)
        print('BACKUP='+str(backup),flush=True)
if __name__=='__main__':main()
